package app.rwun;
import android.Manifest;import android.app.*;import android.content.*;import android.location.*;import android.os.*;import android.widget.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ServiceController;import org.robolectric.shadows.*;import java.time.*;import java.util.*;import static org.junit.Assert.*;
/** Actual foreground recorder driven by timestamped Android Location callbacks; no hardware claim. */
@RunWith(RobolectricTestRunner.class) @GraphicsMode(GraphicsMode.Mode.NATIVE) @Config(sdk=35,manifest=Config.NONE) @LooperMode(LooperMode.Mode.PAUSED)
public class GpsRecordingTest {
 ServiceController<TrackingService> controller;TrackingService service;Application app;long start,epoch;
 @Before public void begin(){app=RuntimeEnvironment.getApplication();app.getSharedPreferences("rwun",0).edit().clear().putBoolean("audio",false).commit();Shadows.shadowOf(app).grantPermissions(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.POST_NOTIFICATIONS);Shadows.shadowOf(app.getSystemService(LocationManager.class)).setProviderEnabled(LocationManager.GPS_PROVIDER,true);controller=Robolectric.buildService(TrackingService.class).create();service=controller.get();service.onStartCommand(new Intent(app,TrackingService.class).setAction("START").putExtra("id","walk:gps-test").putExtra("request","gps-test"),0,1);assertTrue(service.startFailure(),service.active());start=SystemClock.elapsedRealtime();epoch=System.currentTimeMillis();}
 @After public void stop(){service.discard();controller.destroy();}
 Location point(double metres,long offset){Location l=new Location(LocationManager.GPS_PROVIDER);l.setLatitude(-33.9);l.setLongitude(18.4+Math.toDegrees(metres/(6371000*Math.cos(Math.toRadians(-33.9)))));l.setAccuracy(10);l.setElapsedRealtimeNanos((start+offset)*1000000);l.setTime(epoch+offset);return l;}
 void advance(long offset){long delta=start+offset-SystemClock.elapsedRealtime();if(delta>0)ShadowSystemClock.advanceBy(Duration.ofMillis(delta));}
 @Test public void delayedBatchKeepsRecordedMovement(){advance(70000);List<Location> batch=new ArrayList<>();for(int i=0;i<=25;i++)batch.add(point(i*4,1000+i*2000));service.onLocationChanged(batch);assertEquals("100 m recorded inside this session must survive a delayed callback",.100,service.km(),.002);assertTrue("delayed data must not be advertised as fresh GPS",service.status().toLowerCase(Locale.ROOT).contains("delayed"));}
 @Test public void twoKilometresInDelayedBatches(){for(int first=0;first<=1000;first+=50){int last=Math.min(first+49,1000);advance(1000+last*2000+20000);List<Location> batch=new ArrayList<>();for(int i=first;i<=last;i++)batch.add(point(i*2,1000+i*2000));service.onLocationChanged(batch);}assertEquals("delayed GPS must keep the full measured 2 km",2,service.km(),.005);assertTrue("delayed GPS is not a live pace sample",Double.isNaN(service.currentPace()));}
 @Test public void noDistanceShowsWarning()throws Exception{advance(61000);service.onLocationChanged(point(0,60000));assertTrue(service.distanceNeedsAttention());assertTrue(service.status().contains("No GPS distance"));recordingScreen("13-walk-no-distance-warning");}
 @Test public void knownWalkDistanceCanBeSavedWithoutInventingRoute()throws Exception{
  advance(70000);Shadows.shadowOf(app).setComponentNameAndServiceForBindService(new ComponentName(app,TrackingService.class),service.onBind(new Intent()));
  try(var activity=Robolectric.buildActivity(MainActivity.class,new Intent(app,MainActivity.class).putExtra("destination","Run")).setup().visible()){
   MainActivity screen=activity.get();NativePlanningTest.click(screen,"Finish and save");AlertDialog dialog=(AlertDialog)ShadowDialog.getLatestDialog();EditText value=findEntry(dialog.getWindow().getDecorView(),"Known walking distance in kilometres");assertNotNull(value);value.setText("2");dialog.getButton(-1).performClick();
   var walks=new RunStore(app).walks();assertEquals(1,walks.length());var walk=walks.getJSONObject(0);assertEquals(2,walk.getDouble("km"),0);assertEquals(70,walk.getLong("seconds"));assertEquals("Manual walk distance",walk.getString("source"));assertEquals("",walk.getString("route"));assertTrue(new RunStore(app).runs().isEmpty());
  }
 }
 void recordingScreen(String name)throws Exception{Shadows.shadowOf(app).setComponentNameAndServiceForBindService(new ComponentName(app,TrackingService.class),service.onBind(new Intent()));try(var activity=Robolectric.buildActivity(MainActivity.class,new Intent(app,MainActivity.class).putExtra("destination","Run")).setup().visible()){Shadows.shadowOf(Looper.getMainLooper()).idle();assertNotNull(NativePlanningTest.find(activity.get().getWindow().getDecorView(),service.distanceNeedsAttention()?"CHECK DISTANCE":"RECORDING"));NativePlanningTest.shot(activity.get(),name);}}
 static EditText findEntry(View view,String description){if(view instanceof EditText&&description.contentEquals(view.getContentDescription()))return (EditText)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){EditText found=findEntry(((ViewGroup)view).getChildAt(i),description);if(found!=null)return found;}return null;}

 @Test public void twoKilometreWalk()throws Exception{for(int i=0;i<=1000;i++){advance(1000+i*2000);service.onLocationChanged(point(i*2,1000+i*2000));}assertEquals(2,service.km(),.005);assertTrue(service.walking());recordingScreen("14-two-kilometre-walk");}
 @Test public void beforeStartAndFutureFixesDoNotCount(){advance(70000);service.onLocationChanged(point(500,-1000));service.onLocationChanged(point(800,100000));assertEquals(0,service.km(),0);}
 @Test public void duplicateAndOutOfOrderCallbacksDoNotDoubleCount(){advance(12000);service.onLocationChanged(List.of(point(0,1000),point(20,11000)));double distance=service.km();service.onLocationChanged(List.of(point(0,1000),point(20,11000)));assertEquals(distance,service.km(),0);}
 @Test public void pauseAndResumeExcludeMovementWhilePaused(){advance(12000);service.onLocationChanged(List.of(point(0,1000),point(20,11000)));service.togglePause();advance(72000);service.onLocationChanged(point(400,60000));service.togglePause();service.onLocationChanged(point(450,65000));advance(73000);service.onLocationChanged(point(500,73000));advance(83000);service.onLocationChanged(point(520,83000));assertEquals(.040,service.km(),.002);}
 @Test public void longMissingIntervalDoesNotInventDistance(){advance(120000);service.onLocationChanged(List.of(point(0,1000),point(150,119000)));assertEquals(0,service.km(),0);}
 @Test public void poorAccuracyAndTeleportAreRejected(){advance(12000);Location poor=point(500,1000);poor.setAccuracy(100);service.onLocationChanged(poor);service.onLocationChanged(point(0,2000));service.onLocationChanged(point(2000,3000));assertEquals(0,service.km(),0);}
}
